  inline const Entry<Extra> *get_entryZ (int state, unsigned int klass) const
  {
    if (unlikely (klass >= nClasses)) return nullptr;

    const HBUSHORT *states = (this+stateArrayTable).arrayZ;
    const Entry<Extra> *entries = (this+entryTable).arrayZ;

    unsigned int entry = states[state * nClasses + klass];
    DEBUG_MSG (APPLY, nullptr, "e%u", entry);

    return &entries[entry];
  }

  inline bool sanitize (hb_sanitize_context_t *c,
                        unsigned int *num_entries_out = nullptr) const
  {
    TRACE_SANITIZE (this);
    if (unlikely (!(c->check_struct (this) &&
                    classTable.sanitize (c, this)))) return_trace (false);

    const HBUSHORT *states = (this+stateArrayTable).arrayZ;
    const Entry<Extra> *entries = (this+entryTable).arrayZ;

    unsigned int num_classes = nClasses;
    if (unlikely (hb_unsigned_mul_overflows (num_classes, states[0].static_size)))
      return_trace (false);
    unsigned int row_stride = num_classes * states[0].static_size;

    /* Apple 'kern' table has this peculiarity:
     *
     * "Because the stateTableOffset in the state table header is (strictly
     * speaking) redundant, some 'kern' tables use it to record an initial
     * state where that should not be StartOfText. To determine if this is
     * done, calculate what the stateTableOffset should be. If it's different
     * from the actual stateTableOffset, use it as the initial state."
     *
     * We implement this by calling the initial state zero, but allow *negative*
     * states if the start state indeed was not the first state.  Since the code
     * is shared, this will also apply to 'mort' table.  The 'kerx' / 'morx'
     * tables are not affected since those address states by index, not offset.
     */

    int min_state = 0;
    int max_state = 0;
    unsigned int num_entries = 0;

    int state_pos = 0;
    int state_neg = 0;
    unsigned int entry = 0;
    while (min_state < state_neg || state_pos <= max_state)
    {
      if (min_state < state_neg)
      {
        /* Negative states. */
        if (unlikely (hb_unsigned_mul_overflows (min_state, num_classes)))
          return_trace (false);
        if (unlikely (!c->check_array (&states[min_state * num_classes], -min_state, row_stride)))
          return_trace (false);
        if ((c->max_ops -= state_neg - min_state) < 0)
          return_trace (false);
        { /* Sweep new states. */
          const HBUSHORT *stop = &states[min_state * num_classes];
          if (unlikely (stop > states))
            return_trace (false);
          for (const HBUSHORT *p = states; stop < p; p--)
            num_entries = MAX<unsigned int> (num_entries, *(p - 1) + 1);
          state_neg = min_state;
        }
      }

      if (state_pos <= max_state)
      {
        /* Positive states. */
        if (unlikely (!c->check_array (states, max_state + 1, row_stride)))
          return_trace (false);
        if ((c->max_ops -= max_state - state_pos + 1) < 0)
          return_trace (false);
        { /* Sweep new states. */
          if (unlikely (hb_unsigned_mul_overflows ((max_state + 1), num_classes)))
            return_trace (false);
          const HBUSHORT *stop = &states[(max_state + 1) * num_classes];
          if (unlikely (stop < states))
            return_trace (false);
          for (const HBUSHORT *p = &states[state_pos * num_classes]; p < stop; p++)
            num_entries = MAX<unsigned int> (num_entries, *p + 1);
          state_pos = max_state + 1;
        }
      }

      if (unlikely (!c->check_array (entries, num_entries)))
        return_trace (false);
      if ((c->max_ops -= num_entries - entry) < 0)
        return_trace (false);
      { /* Sweep new entries. */
        const Entry<Extra> *stop = &entries[num_entries];
        for (const Entry<Extra> *p = &entries[entry]; p < stop; p++)
        {
          int newState = new_state (p->newState);
          min_state = MIN (min_state, newState);
          max_state = MAX (max_state, newState);
        }
        entry = num_entries;
      }
    }

    if (num_entries_out)
      *num_entries_out = num_entries;

    return_trace (true);
  }

  protected:
  HBUINT        nClasses;       /* Number of classes, which is the number of indices
                                 * in a single line in the state array. */
  OffsetTo<ClassType, HBUINT, false>
                classTable;     /* Offset to the class table. */
  OffsetTo<UnsizedArrayOf<HBUSHORT>, HBUINT, false>
                stateArrayTable;/* Offset to the state array. */
  OffsetTo<UnsizedArrayOf<Entry<Extra> >, HBUINT, false>
                entryTable;     /* Offset to the entry array. */

  public:
  DEFINE_SIZE_STATIC (4 * sizeof (HBUINT));
};

struct ClassTable
{
  inline unsigned int get_class (hb_codepoint_t glyph_id, unsigned int outOfRange) const
  {
    unsigned int i = glyph_id - firstGlyph;
    return i >= classArray.len ? outOfRange : classArray.arrayZ[i];
  }
  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);
    return_trace (c->check_struct (this) && classArray.sanitize (c));
  }
  protected:
  GlyphID               firstGlyph;     /* First glyph index included in the trimmed array. */
  ArrayOf<HBUINT8>      classArray;     /* The class codes (indexed by glyph index minus
                                         * firstGlyph). */
  public:
  DEFINE_SIZE_ARRAY (4, classArray);
};

struct ObsoleteTypes
{
  static const bool extended = false;
  typedef HBUINT16 HBUINT;
  typedef HBUINT8 HBUSHORT;
  struct ClassType : ClassTable
  {
    inline unsigned int get_class (hb_codepoint_t glyph_id,
                                   unsigned int num_glyphs HB_UNUSED,
                                   unsigned int outOfRange) const
    {
      return ClassTable::get_class (glyph_id, outOfRange);
    }
  };
  template <typename T>
  static inline unsigned int offsetToIndex (unsigned int offset,
                                            const void *base,
                                            const T *array)
  {
    return (offset - ((const char *) array - (const char *) base)) / sizeof (T);
  }
  template <typename T>
  static inline unsigned int wordOffsetToIndex (unsigned int offset,
                                                const void *base,
                                                const T *array)
  {
    return offsetToIndex (2 * offset, base, array);
  }
};
struct ExtendedTypes
{
  static const bool extended = true;
  typedef HBUINT32 HBUINT;
  typedef HBUINT16 HBUSHORT;
  struct ClassType : Lookup<HBUINT16>
  {
    inline unsigned int get_class (hb_codepoint_t glyph_id,
                                   unsigned int num_glyphs,
                                   unsigned int outOfRange) const
    {
      const HBUINT16 *v = get_value (glyph_id, num_glyphs);
      return v ? *v : outOfRange;
    }
  };
  template <typename T>
  static inline unsigned int offsetToIndex (unsigned int offset,
                                            const void *base,
                                            const T *array)
  {
    return offset;
  }
  template <typename T>
  static inline unsigned int wordOffsetToIndex (unsigned int offset,
                                                const void *base,
                                                const T *array)
  {
    return offset;
  }
};

template <typename Types, typename EntryData>
struct StateTableDriver
{
  inline StateTableDriver (const StateTable<Types, EntryData> &machine_,
                           hb_buffer_t *buffer_,
                           hb_face_t *face_) :
              machine (machine_),
              buffer (buffer_),
              num_glyphs (face_->get_num_glyphs ()) {}

  template <typename context_t>
  inline void drive (context_t *c)
  {
    if (!c->in_place)
      buffer->clear_output ();

    int state = StateTable<Types, EntryData>::STATE_START_OF_TEXT;
    bool last_was_dont_advance = false;
    for (buffer->idx = 0; buffer->successful;)
    {
      unsigned int klass = buffer->idx < buffer->len ?
                           machine.get_class (buffer->info[buffer->idx].codepoint, num_glyphs) :
                           (unsigned) StateTable<Types, EntryData>::CLASS_END_OF_TEXT;
      DEBUG_MSG (APPLY, nullptr, "c%u at %u", klass, buffer->idx);
      const Entry<EntryData> *entry = machine.get_entryZ (state, klass);
      if (unlikely (!entry))
        break;

      /* Unsafe-to-break before this if not in state 0, as things might
       * go differently if we start from state 0 here.
       *
       * Ugh.  The indexing here is ugly... */
      if (state && buffer->backtrack_len () && buffer->idx < buffer->len)
      {
        /* If there's no action and we're just epsilon-transitioning to state 0,
         * safe to break. */
        if (c->is_actionable (this, entry) ||
            !(entry->newState == StateTable<Types, EntryData>::STATE_START_OF_TEXT &&
              entry->flags == context_t::DontAdvance))
          buffer->unsafe_to_break_from_outbuffer (buffer->backtrack_len () - 1, buffer->idx + 1);
      }

      /* Unsafe-to-break if end-of-text would kick in here. */
      if (buffer->idx + 2 <= buffer->len)
      {
        const Entry<EntryData> *end_entry = machine.get_entryZ (state, 0);
        if (c->is_actionable (this, end_entry))
          buffer->unsafe_to_break (buffer->idx, buffer->idx + 2);
      }

      if (unlikely (!c->transition (this, entry)))
        break;

      last_was_dont_advance = (entry->flags & context_t::DontAdvance) && buffer->max_ops-- > 0;

      state = machine.new_state (entry->newState);
      DEBUG_MSG (APPLY, nullptr, "s%d", state);

      if (buffer->idx == buffer->len)
        break;

      if (!last_was_dont_advance)
        buffer->next_glyph ();
    }

    if (!c->in_place)
    {
      for (; buffer->successful && buffer->idx < buffer->len;)
        buffer->next_glyph ();
      buffer->swap_buffers ();
    }
  }

  public:
  const StateTable<Types, EntryData> &machine;
  hb_buffer_t *buffer;
  unsigned int num_glyphs;
};


